import random

import pytest
import quopri

import qp


def test_vector_cafe():
    encoded = qp.encode(b"caf\xc3\xa9")
    assert b"=C3=A9" in encoded


def test_vector_trailing_space_encoded():
    encoded = qp.encode(b"hello \nworld\n")
    assert b"hello=20\nworld\n" == encoded


def test_vector_printable_passthrough():
    assert qp.encode(b"Hello-World_123!") == b"Hello-World_123!"


def test_vector_equals_sign():
    assert qp.encode(b"a=b") == b"a=3Db"


@pytest.mark.parametrize(
    "raw,expected",
    [
        (b"", b""),                       # empty input
        (b"\n", b"\n"),                   # bare newline
        (b"a=\nb", b"ab"),                # soft break
        (b"a=\r\nb", b"ab"),              # soft break, CRLF style
        (b"a=3Db", b"a=b"),               # uppercase hex
        (b"a=3db", b"a=b"),               # lowercase hex
        (b"a=3D b", b"a=D b".replace(b"D", b"3D")),  # invalid: '=3 ' keeps '3'
    ],
)
def test_decode_vectors(raw, expected):
    if raw == b"a=3D b":
        expected = b"a=3D b"[:0] + b"a=3 b"  # '=3' invalid (' ' not hex) -> literal '=','3'
    assert qp.decode(raw) == expected


def test_invalid_escape_left_literal_like_quopri():
    for bad in (b"=zz", b"=G1", b"=1", b"=", b"a=Xb"):
        assert qp.decode(b"x" + bad + b"y") == quopri.decodestring(b"x" + bad + b"y")


def test_decode_matches_quopri_on_random_garbage():
    rng = random.Random(7)
    for _ in range(500):
        x = bytes(rng.randrange(256) for _ in range(rng.randint(0, 60)))
        e = quopri.encodestring(x)
        assert qp.decode(e) == x
        assert quopri.decodestring(qp.encode(x)) == x


def test_differential_roundtrip_500_seeded():
    rng = random.Random(1234)
    for i in range(500):
        x = bytes(rng.randrange(256) for _ in range(rng.randint(0, 512)))
        ours_decodes_theirs = qp.decode(quopri.encodestring(x)) == x
        theirs_decodes_ours = quopri.decodestring(qp.encode(x)) == x
        assert ours_decodes_theirs, f"decode failed on sample {i}: {x!r}"
        assert theirs_decodes_ours, f"encode failed on sample {i}: {x!r}"


def test_no_line_exceeds_76_chars_10kb():
    rng = random.Random(99)
    blob = bytes(rng.randrange(256) for _ in range(10_000))
    encoded = qp.encode(blob)
    for lineno, line in enumerate(encoded.split(b"\n")):
        assert len(line) <= 76, f"line {lineno} too long: {len(line)}"


